class Table {

    Pair[] table;

    Table(int size) {
        table = new Pair[size];
    }

    int hashCode(int key) {
        return key % table.length;
    }

    void print() {
        System.out.println(Arrays.toString(this.table));
    }

    void put(int value) {

        for (int i = 0; i <= table.length ; i++) {

