        int i = 0;
        Node aux = head;
        while (aux != null && aux.value != value) {
            aux = aux.next;
            i++;
        }
        return (aux == null) ? -1 : i;
    }

    public boolean remove(int value) {

        if (!isEmpty()) {

            if (this.head.value == value) {
                this.head = this.head.next;
                this.size--;
                return true;
            }

            Node prev = null;
            Node aux = head;

            while (aux != null && aux.value != value) {
                prev = aux;
                aux = aux.next;
            }

            if (aux == null) return false;
            else {
                prev.next = aux.next;
                this.size--;
                return true;
            }

        }

        return false;


